import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import './Home.css';
import Img1 from '../assets/images/img1.jpeg';
import Img2 from '../assets/images/img2.jpeg';

  const partners = [
  {
    name: 'Company A',
    logo: Img1,
    description: 'Company A specializes in smart home systems and automation protocols.',
    website: 'https://www.google.com'
  },
  {
    name: 'Company B',
    logo: Img2,
    description: 'Company B offers high-end IoT solutions and energy management tools.',
    website: 'https://www.youtube.com'
  }
];

function Home() {
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);
  const partnersRef = useRef(null);
const [partnersVisible, setPartnersVisible] = useState(false);

useEffect(() => {
  const observer = new IntersectionObserver(
    entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          setPartnersVisible(true);
          observer.disconnect();
        }
      });
    },
    { threshold: 0.3 }
  );

  if (partnersRef.current) {
    observer.observe(partnersRef.current);
  }

  return () => observer.disconnect();
}, []);


  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.disconnect(); // Remove after first trigger
          }
        });
      },
      { threshold: 0.3 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section id="home" ref={sectionRef} className={`hero ${isVisible ? 'visible' : ''}`}>
      <div className="container hero-inner">
        <div className="hero-copy">
          <h1 className={`fade-in-hero ${isVisible ? 'visible' : ''}`}>
    Your Space Can Now Listen, Learn and Respond!
  </h1>
          <p className={`lead fade-in-hero ${isVisible ? 'visible' : ''}`} style={{ transitionDelay: '200ms' }}>
            Smart home & building automation solutions that make everyday living intelligent, efficient and secure.
          </p>
          <Link
  className={`btn fade-in-hero ${isVisible ? 'visible' : ''}`}
  style={{ transitionDelay: '400ms' }}
  to="/products"
>Our Products</Link>
        </div>

<div className={`hero-media fade-in-hero ${isVisible ? 'visible' : ''}`}>
          <img
            src="https://images.unsplash.com/photo-1506765515384-028b60a970df?q=80&w=1200&auto=format&fit=crop&ixlib=rb-4.0.3&s=placeholder"
            alt="Smart home"
          />
        </div>
      </div>
    <section ref={sectionRef} className={`features fade-in-section ${isVisible ? 'visible' : ''}`}>
      <div className="feature-block">
        <div className="text">
          <h1>Innovative Solutions</h1>
          <p>
            At Kilowatt Electric, we specialize in smart home and building automation solutions designed to make everyday living more intelligent, efficient, and secure. Our systems seamlessly integrate lighting, climate control, security, entertainment, energy management, and more—delivering unmatched convenience and control at your fingertips.
          </p>
        </div>
        <img src={Img1} alt="Modern Kitchen" />
      </div>

      <div className="feature-block reverse">
        <img src={Img2} alt="Dining Room" />
        <div className="text">
          <h1>Seamless Integration</h1>
          <p>
            Whether it’s a private home, commercial space, hotel, or healthcare facility, we customize each solution to suit your unique needs, ensuring comfort, sustainability, and future-ready technology. With a focus on intuitive design and reliable performance, we help you create smarter spaces that adapt to your lifestyle or business operations—while reducing energy costs and increasing property value.
          </p>
        </div>
      </div>
    </section>
    <section
        ref={sectionRef}
        className={`partners-section fade-in-section ${isVisible ? 'visible' : ''}`}>
        <div className="container">
          <h2 className="section-title">Our Partners</h2>
          <div className="partners-grid">
            {partners.map((partner, index) => (
               <div
    key={index}
    className={`partner-card fade-in-card ${isVisible ? 'visible' : ''}`}
    style={{ transitionDelay: `${index * 100}ms` }}>
                <img src={partner.logo} alt={partner.name} />
                <h3>{partner.name}</h3>
                <p>{partner.description}</p>
                <a
                  className="know-more-btn"
                  href={partner.website}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Know More
                </a>
              </div>
            ))}
          </div>
        </div>
      </section>
    </section>
  );
}
export default Home;
